def parse_duration_seconds(text: str) -> int:
    import re
    if not text:
        return -1
    m = re.fullmatch(r'(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?', text)
    if not m or not any(m.groups()):
        return -1
    h, mi, s = (int(g) if g else 0 for g in m.groups())
    return h * 3600 + mi * 60 + s

