def compress_sorted_ranges(nums: list) -> list:
    if not nums:
        return []
    uniq = []
    for x in nums:
        if not uniq or uniq[-1] != x:
            uniq.append(x)
    out = []
    start = prev = uniq[0]
    for x in uniq[1:]:
        if x == prev + 1:
            prev = x
        else:
            out.append(str(start) if start == prev else f'{start}-{prev}')
            start = prev = x
    out.append(str(start) if start == prev else f'{start}-{prev}')
    return out
